INSERT INTO `activity` VALUES (1,1,1,'校园歌手大赛','一年一度的校园歌手大赛开始报名啦！展示你的歌喉，赢取丰厚奖品，欢迎所有喜欢唱歌的同学参加。','https://picsum.photos/600/400?random=801',2,'2024-01-20','18:00:00','21:00:00','大礼堂',50,32,0.00,'微信：singer2024',1,NULL,0,1250,1,'2026-10-07 11:25:31','2026-10-09 14:38:09',0),(2,1,2,'3V3篮球挑战赛','体育部组织的3V3篮球挑战赛，组队报名，冠军队伍有奖金和奖杯，欢迎篮球爱好者踊跃参加。','https://picsum.photos/600/400?random=802',1,'2024-01-18','09:00:00','17:00:00','篮球场',64,48,0.00,'QQ群：123456789',1,NULL,1,890,0,'2026-10-07 11:25:31','2026-10-09 14:00:46',0),(3,1,3,'考研经验分享会','邀请成功保研和考研上岸的学长学姐分享经验，解答大家的疑问，有意向考研的同学不要错过。','https://picsum.photos/600/400?random=803',0,'2024-01-17','19:00:00','21:00:00','图书馆报告厅',200,157,0.00,'微信：kaoyan_share',1,NULL,1,2340,1,'2026-10-07 11:25:31','2026-10-09 13:42:32',0),(4,1,4,'周末志愿服务活动','本周末去敬老院做志愿服务，陪老人聊天、表演节目，弘扬志愿精神，欢迎有爱心的同学加入。','https://picsum.photos/600/400?random=804',3,'2024-01-21','08:00:00','16:00:00','阳光敬老院',30,18,0.00,'微信：volunteer_pku',1,NULL,1,456,0,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(5,1,5,'新生编程马拉松','面向大一新生的编程比赛，24小时内完成指定项目，锻炼编程能力和团队协作，丰厚奖品等你来拿。','https://picsum.photos/600/400?random=805',0,'2024-01-25','09:00:00','18:00:00','计算机学院楼',100,67,0.00,'邮箱：hackathon@pku.edu.cn',1,NULL,1,678,0,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(6,1,6,'校园摄影大赛','用镜头记录校园的美好瞬间，摄影大赛开始征稿啦，题材不限，获奖作品将在校园展出。','https://picsum.photos/600/400?random=806',2,'2024-02-01','00:00:00','23:59:59','线上活动',0,89,0.00,'微信：photo_contest',1,NULL,1,520,0,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(7,1,7,'羽毛球友谊赛','学院之间的羽毛球友谊赛，单打双打都有，以球会友，增进交流，欢迎羽毛球爱好者参加。','https://picsum.photos/600/400?random=807',1,'2024-01-19','14:00:00','18:00:00','羽毛球馆',32,24,10.00,'QQ：987654321',1,NULL,1,345,0,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(8,1,8,'桌游聚会','周末桌游聚会，狼人杀、剧本杀、三国杀都有，认识新朋友，一起度过愉快的周末时光。','https://picsum.photos/600/400?random=808',2,'2024-01-20','14:00:00','20:00:00','学生活动中心',20,15,20.00,'微信：boardgame_pku',1,NULL,1,280,0,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(9,1,1,'校园歌手大赛海选','一年一度的校园歌手大赛开始啦！无论你是麦霸还是洗澡歌神，都来一展歌喉吧，奖品丰厚！','https://picsum.photos/600/300?random=801',1,'2024-03-15','18:00:00','21:00:00','大学生活动中心',50,42,0.00,NULL,1,NULL,1,567,0,'2026-10-08 16:23:57','2026-10-08 16:23:57',0),(10,1,2,'编程马拉松24小时','24小时不间断编程挑战，组队参赛，主题现场公布，提供夜宵和咖啡，等你来战！','https://picsum.photos/600/300?random=802',1,'2024-03-20','09:00:00','09:00:00','创新创业基地',100,78,0.00,NULL,1,NULL,1,423,0,'2026-10-08 16:23:57','2026-10-08 16:23:57',0),(11,1,3,'春季运动会报名','春季田径运动会开始报名，项目齐全，团体赛个人赛都有，各班踊跃报名！','https://picsum.photos/600/300?random=803',0,'2024-04-10','08:00:00','18:00:00','校体育场',500,356,0.00,NULL,1,NULL,1,890,0,'2026-10-08 16:23:57','2026-10-08 16:23:57',0),(12,1,4,'读书分享会','本月读书主题：《三体》。欢迎科幻迷来一起讨论宇宙、文明和黑暗森林法则。','https://picsum.photos/600/300?random=804',2,'2024-03-18','19:00:00','21:00:00','图书馆3楼会议室',30,25,0.00,NULL,1,NULL,1,156,0,'2026-10-08 16:23:57','2026-10-08 16:23:57',0),(13,1,12,'a',NULL,NULL,0,'2026-10-20','14:00:00','16:00:00','L',0,0,0.00,NULL,1,NULL,0,0,0,'2026-10-09 13:29:18','2026-10-09 13:29:18',0),(14,1,12,'a',NULL,NULL,0,'2026-10-20','14:00:00','16:00:00','L',0,0,0.00,NULL,0,NULL,1,0,0,'2026-10-09 13:42:32','2026-10-09 13:42:32',0),(15,1,12,'E2E activity','test',NULL,0,'2026-11-20','14:00:00','16:00:00','gym',50,0,0.00,NULL,0,NULL,1,0,0,'2026-10-09 13:45:20','2026-10-09 13:45:20',0),(16,1,12,'E2E activity','test',NULL,0,'2026-11-20','14:00:00','16:00:00','gym',50,0,0.00,NULL,0,NULL,1,0,0,'2026-10-09 13:51:31','2026-10-09 13:51:31',0),(17,1,12,'a',NULL,NULL,0,'2026-10-20','14:00:00','16:00:00','L',0,0,0.00,NULL,0,NULL,1,0,0,'2026-10-09 13:51:37','2026-10-09 13:51:37',0),(18,1,12,'E2E activity','test',NULL,0,'2026-11-20','14:00:00','16:00:00','gym',50,0,0.00,NULL,0,NULL,1,0,0,'2026-10-09 14:00:38','2026-10-09 14:00:39',0),(19,1,12,'a',NULL,NULL,0,'2026-10-20','14:00:00','16:00:00','L',0,0,0.00,NULL,0,NULL,1,0,0,'2026-10-09 14:00:46','2026-10-09 14:00:46',0),(20,1,12,'t',NULL,NULL,0,'2026-12-01','10:00:00','12:00:00','l',0,1,0.00,NULL,0,NULL,1,0,0,'2026-10-09 14:00:57','2026-10-09