INSERT INTO `errand_order` VALUES (1,'ERR202401150001',1,1,12,0,'帮买一杯奶茶','帮我买一杯喜茶的多肉葡萄，少糖少冰，谢谢！',NULL,'学校东门喜茶店','32号楼302室','张三','13800138001','2024-01-15 15:00:00',5.00,28.00,2.00,35.00,5,'管理员取消','2024-01-15 14:00:00','2024-01-15 14:45:00','2026-10-07 11:25:31','2026-10-09 14:38:09',0),(2,'ERR202401150002',1,2,NULL,1,'送一份资料到教学楼','有一份课程设计资料需要送到一教305教室，是给老师的，麻烦小心点别弄坏了。',NULL,'28号楼501室','一教305教室','李四','13800138002','2024-01-15 16:00:00',8.00,0.00,0.00,8.00,1,NULL,NULL,NULL,'2026-10-07 11:25:31','2026-10-08 16:54:13',0),(3,'ERR202401150003',1,3,13,2,'帮忙取个外卖','外卖到了但是我在上课走不开，帮忙取一下送到三教201教室门口。',NULL,'学校南门外卖柜','三教201教室','王五','13800138003','2024-01-15 12:30:00',5.00,0.00,1.00,6.00,2,NULL,'2024-01-15 12:10:00',NULL,'2026-10-07 11:25:31','2026-10-09 13:42:32',0),(4,'ERR202401140004',1,4,NULL,0,'帮买感冒药','感冒了不想动，帮忙去校医院买一盒999感冒灵和体温计，谢谢。',NULL,'校医院药房','45号楼101室','赵六','13800138004','2024-01-14 19:00:00',6.00,35.00,4.00,45.00,1,NULL,'2024-01-14 18:30:00','2024-01-14 19:10:00','2026-10-07 11:25:31','2026-10-08 18:04:55',0),(5,'ERR202401140005',1,5,NULL,3,'帮忙搬东西','毕业要搬宿舍，东西有点多，找个力气大的同学帮忙搬一下，从5楼搬到楼下。',NULL,'12号楼502室','学校南门','孙七','13800138005','2024-01-14 10:00:00',50.00,0.00,10.00,60.00,1,NULL,NULL,NULL,'2026-10-07 11:25:31','2026-10-08 16:54:13',0),(6,'ERR202401130006',1,6,7,1,'送伞到图书馆','下雨了没带伞，麻烦送一把伞到图书馆二楼，我在靠窗的位置。',NULL,'22号楼305室','图书馆二楼','周八','13800138006','2024-01-13 17:00:00',8.00,0.00,2.00,10.00,2,NULL,'2024-01-13 16:40:00','2024-01-13 17:05:00','2026-10-07 11:25:31','2026-10-08 16:54:13',0),(7,'ERR202401130007',1,7,8,0,'帮买水果','帮忙买两斤苹果和一串香蕉，要新鲜的，水果店在南门那边。',NULL,'南门水果店','18号楼601室','吴九','13800138007','2024-01-13 20:00:00',5.00,20.00,0.00,25.00,3,NULL,'2024-01-13 19:30:00',NULL,'2026-10-07 11:25:31','2026-10-08 16:54:13',0),(8,'ERR202401120008',1,8,1,2,'取快递送到宿舍','有个大包裹在驿站，我一个人搬不动，帮忙取一下送到宿舍楼下。',NULL,'菜鸟驿站B区','8号楼102室','郑十','13800138008','2024-01-12 16:00:00',10.00,0.00,5.00,15.00,4,NULL,'2024-01-12 15:30:00','2024-01-12 16:20:00','2026-10-07 11:25:31','2026-10-08 16:54:13',0),(9,'ERR1