--
-- Table structure for table `express_order`
--

DROP TABLE IF EXISTS `express_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `express_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(32) NOT NULL COMMENT '订单号',
  `school_id` bigint NOT NULL COMMENT '学校ID',
  `user_id` bigint NOT NULL COMMENT '下单用户ID',
  `picker_id` bigint DEFAULT NULL COMMENT '接单用户ID',
  `express_company` varchar(32) NOT NULL COMMENT '快递公司',
  `pickup_code` varchar(32) NOT NULL COMMENT '取件码',
  `pickup_address` varchar(256) NOT NULL COMMENT '取件地址',
  `delivery_address` varchar(256) NOT NULL COMMENT '送达地址',
  `weight` tinyint DEFAULT '0' COMMENT '重量(0:小件 1:中件 2:大件)',
  `receiver_name` varchar(32) NOT NULL COMMENT '收货人姓名',
  `receiver_phone` varchar(20) NOT NULL COMMENT '收货人电话',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `service_fee` decimal(10,2) NOT NULL COMMENT '服务费',
  `tip` decimal(10,2) DEFAULT '0.00' COMMENT '小费',
  `total_amount` decimal(10,2) NOT NULL COMMENT '总金额',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '订单状态(0:待接单 1:已接单 2:配送中 3:已完成 4:已取消 5:已退款)',
  `cancel_reason` varchar(256) DEFAULT NULL COMMENT '取消原因',
  `accept_time` datetime DEFAULT NULL COMMENT '接单时间',
  `complete_time` datetime DEFAULT NULL COMMENT '完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_status` (`status`),
  KEY `idx_picker_id` (`picker_id`),
  KEY `idx_school_status_time` (`school_id`,`status`,`create_time`),
  CONSTRAINT `fk_express_picker` FOREIGN KEY (`picker_id`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_express_school` FOREIGN KEY (`school_id`) REFERENCES `school` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_express_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=631 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='快递代取订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `express_order`
--

LOCK TABLES `express_order` WRITE;
/*!40000 ALTER TABLE `express_order` DISABLE KEYS */;
