--
-- Table structure for table `feedback`
--

DROP TABLE IF EXISTS `feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `feedback` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint DEFAULT NULL COMMENT '学校ID',
  `user_id` bigint NOT NULL COMMENT '反馈用户ID',
  `type` tinyint NOT NULL DEFAULT '0' COMMENT '反馈类型(0:功能建议 1:BUG反馈 2:投诉举报 3:其他)',
  `title` varchar(128) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '反馈内容',
  `images` varchar(2048) DEFAULT NULL COMMENT '图片(逗号分隔)',
  `contact` varchar(64) DEFAULT NULL COMMENT '联系方式',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态(0:待处理 1:处理中 2:已完成)',
  `reply` text COMMENT '回复内容',
  `reply_time` datetime DEFAULT NULL COMMENT '回复时间',
  `reply_admin_id` bigint DEFAULT NULL COMMENT '回复管理员ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_status` (`status`),
  KEY `idx_reply_admin_id` (`reply_admin_id`),
  CONSTRAINT `fk_feedback_admin` FOREIGN KEY (`reply_admin_id`) REFERENCES `admin` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_feedback_school` FOREIGN KEY (`school_id`) REFERENCES `school` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_feedback_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户反馈表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `feedback`
--

LOCK TABLES `feedback` WRITE;
/*!40000 ALTER TABLE `feedback` DISABLE KEYS */;
INSERT INTO `feedback` VALUES (1,1,1,0,'建议增加匿名发帖功能','希望论坛能增加匿名发帖的功能，有些话题不太好意思用真实身份发。',NULL,'13800138001',2,'感谢您的建议，匿名功能已在开发计划中，预计下个版本上线，敬请期待！','2024-01-10 14:30:00',2,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(2,1,2,1,'快递订单无法支付','下单快递代取后，点击支付没反应，试了好几次都不行，希望尽快修复。',NULL,'13800138002',1,NULL,NULL,NULL,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(3,1,3,2,'有人发布虚假商品','看到有人发布的二手商品明显是假的，价格低得离谱，希望管理员能审核严格一点。',NULL,'13800138003',2,'感谢您的举报，我们已经下架了该商品并对发布者进行了警告处理，后续会加强审核。','2024-01-12 10:00:00',2,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(4,1,4,0,'希望增加夜间模式','晚上刷手机太亮了，希望能加个夜间模式或者深色主题，保护眼睛。',NULL,'13800138004',0,NULL,NULL,NULL,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(5,1,5,1,'头像上传失败','换头像的时候一直上传失败，试了好多次都不行，图片也不大啊。',NULL,'13800138005',2,'您好，该问题已修复，您可以重新尝试上传头像。如果仍有问题请联系客服。','2024-01-13 16:00:00',2,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(6,1,6,3,'其他问题咨询','我想咨询一下怎么成为跑腿员，需要什么条件吗？',NULL,'13800138006',2,'您好，成为跑腿员需要完成实名认证并缴纳押金，具体可在跑腿页面点击\"成为跑手\"查看详情。','2024-01-14 09:30:00',2,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(7,1,12,0,'t','c',NULL,NULL,0,NULL,NULL,NULL,'2026-10-09 13:42:32','2026-10-09 13:42:32',0),(8,1,12,1,'E2E fb','body',NULL,'wx',0,NULL,NULL,NULL,'2026-10-09 13:45:20','2026-10-09 13:45:20',0);
/*!40000 ALTER TABLE `feedback` ENABLE KEYS */;
UNLOCK TABLES;

