/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `game_buddy` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `school_id` bigint NOT NULL COMMENT '学校ID',
  `user_id` bigint NOT NULL COMMENT '发布者ID',
  `game_name` varchar(64) NOT NULL COMMENT '游戏名称',
  `title` varchar(128) NOT NULL COMMENT '标题',
  `description` varchar(512) DEFAULT NULL COMMENT '描述',
  `game_level` varchar(32) DEFAULT NULL COMMENT '游戏段位/等级',
  `play_mode` varchar(32) DEFAULT NULL COMMENT '玩法模式',
  `contact_way` varchar(128) DEFAULT NULL COMMENT '联系方式',
  `play_time` varchar(64) DEFAULT NULL COMMENT '可玩时间',
  `gender` tinyint DEFAULT '2' COMMENT '性别要求(0:男 1:女 2:不限)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(0:已结束 1:招募中)',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_game_name` (`game_name`),
  KEY `idx_school_status_time` (`school_id`,`status`,`create_time`),
  CONSTRAINT `fk_game_school` FOREIGN KEY (`school_id`) REFERENCES `school` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_game_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='游戏搭子表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `game_buddy`
--

LOCK TABLES `game_buddy` WRITE;
/*!40000 ALTER TABLE `game_buddy` DISABLE KEYS */;
INSERT INTO `game_buddy` VALUES (1,1,1,'王者荣耀','找个钻石以上的队友双排','我是边路玩家，实力还行，找个打野或者射手双排上分，最好是钻石以上段位，能开语音最好。','星耀','排位赛','微信：zhangsan_game','晚上8点-11点',2,1,234,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(2,1,2,'英雄联盟','周末一起打灵活组排','黄金段位，主打中单，周末有空的小伙伴一起玩，不喷人，开心游戏最重要。','黄金','灵活组排','QQ：123456789','周六周日全天',2,1,156,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(3,1,3,'原神','找个一起刷本的搭子','58级老玩家，什么本都能打，找个萌新或者回归玩家一起玩，带你刷圣遗物刷周本。','58级','联机副本','微信：wangyu_genshin','晚上7点-10点',1,1,312,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(4,1,4,'和平精英','四缺一，来个会玩的','王牌段位，固定三缺一，来个猛男队友，最好会打狙的，晚上一起上分。','王牌','四排','QQ：987654321','每天晚上',0,1,278,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(5,1,5,'CSGO','找5黑队友打天梯','双AK段位，打了好多年了，找几个队友一起打5黑天梯，娱乐为主，输赢不重要。','双AK','竞技模式','微信：sunqi_csgo','周末下午',0,1,189,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(6,1,6,'动物森友会','找个好友一起玩','刚入手动森，岛上什么都没有，找个好友串门，互相送点水果和家具。','新手','休闲','微信：zhouba_acnh','随时都可以',1,1,95,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(7,1,7,'永劫无间','三排找队友','陨星段位，主打妖刀姬，找两个队友一起三排上修罗，配合好就行。','陨星','三排','QQ：456789012','晚上9点后',2,1,145,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(8,1,8,'我的世界','找建筑师一起建服务器','想搞个生存服务器，找几个喜欢建筑的小伙伴一起玩，长期玩的来。','资深玩家','生存服务器','微信：zhengshi_mc','周末及假期',2,1,210,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(9,1,12,'LOL','LOL Diamond 找搭子','d','Diamond','5v5','wx',NULL,2,1,0,'2026-10-09 13:42:31','2026-10-09 13:42:31',0),(10,1,12,'LOL','LOL Diamond 找搭子','duo','Diamond','5v5','wx',NULL,2,1,0,'2026-10-09 13:45:20','2026-10-09 13:45:20',0),(11,1,12,'LOL','LOL Diamond 找搭子','duo','Diamond','5v5','wx',NULL,2,1,0,'2026-10-09 13:51:31','2026-10-09 13:51:31',0),(12,1,12,'LOL','LOL Diamond 找搭子','d','Diamond','5v5','wx',NULL,2,1,0,'2026-10-09 13:51:37','2026-10-09 13:51:37',0),(13,1,12,'LOL','LOL Diamond 找搭子','duo','Diamond','5v5','wx',NULL,2,1,0,'2026-10-09 14:00:38','2026-10-09 14:00:38',0),(14,1,12,'LOL','LOL Diamond 找搭子','d','Diamond','5v5','wx',NULL,2,1,0,'2026-10-09 14:00:46','2026-10-09 14:00:46',0),(16,19,1,'王者荣耀','王者荣耀 找搭子（重庆第二