INSERT INTO `goods` VALUES (1,1,1,'九成新iPad Air4 64G','自用iPad Air4 64G 深空灰色，购买一年多，外观完好无划痕，配原装充电器和保护套，因换新机所以出掉。',2800.00,'https://picsum.photos/400/400?random=501,https://picsum.photos/400/400?random=502',1,0,1,NULL,156,'2026-10-07 11:25:31','2026-10-09 14:38:09',0),(2,2,1,'高等数学同济第七版上下册','大一用过的高数教材，笔记齐全，适合预习和复习，书页干净无涂鸦。',25.00,'https://picsum.photos/400/400?random=503',2,1,1,NULL,89,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(3,3,1,'宿舍神器床上书桌','大学四年必备床上书桌，可折叠，带抽屉和杯架，八成新，毕业带不走便宜出。',35.00,'https://picsum.photos/400/400?random=504,https://picsum.photos/400/400?random=505',3,1,1,NULL,234,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(4,4,1,'Nike Air Force 1 42码','白色空军一号，42码，穿了几次有点小，鞋盒都在，支持验货，非真假问题不退。',450.00,'https://picsum.photos/400/400?random=506',4,1,1,NULL,312,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(5,5,1,'迪卡侬山地自行车','迪卡侬入门级山地车，26寸，骑了半年左右，刹车变速都正常，适合日常通勤。',600.00,'https://picsum.photos/400/400?random=507,https://picsum.photos/400/400?random=508',5,1,1,NULL,178,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(6,6,1,'小米手环7 NFC版','小米手环7 NFC版，支持门禁卡和公交卡，屏幕完好，表带正常使用痕迹，充电器齐全。',150.00,'https://picsum.photos/400/400?random=509',1,1,1,NULL,95,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(7,7,1,'英语四级真题试卷','星火英语四级真题，2023年版本，做了两套就考过了，剩下的基本全新，附答案解析。',15.00,'https://picsum.photos/400/400?random=510',2,1,1,NULL,67,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(8,8,1,'懒人沙发豆袋椅','宿舍懒人沙发，豆袋椅，灰色，可拆洗，九成新，买了没怎么用，占地儿出了。',80.00,'https://picsum.photos/400/400?random=511',3,1,1,NULL,145,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(9,9,1,'罗技G304无线鼠标','罗技G304无线游戏鼠标，黑色，使用半年，功能正常，手感好，续航给力。',180.00,'https://picsum.photos/400/400?random=512',1,1,1,NULL,76,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(10,10,1,'瑜伽垫加厚15mm','TPE瑜伽垫，加厚15mm，加长加宽，紫色，几乎全新，买了没用几次就闲置了。',45.00,'https://picsum.photos/400/400?random=513',5,1,1,NULL,52,'2026-10-07 11:25:31','2026-10-08 16:26:28',0),(11,1,1,'iPad Pro 2020 11寸 128G','iPad Pro 2020款 11寸 128G 深空灰，带妙控键盘和二代笔，平时用来记笔记看视频，因换新机出售。',4200.00,'https://picsum.