--
-- Table structure for table `lost_found`
--

DROP TABLE IF EXISTS `lost_found`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lost_found` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '发布者ID',
  `school_id` bigint DEFAULT NULL COMMENT '学校ID',
  `type` tinyint NOT NULL COMMENT '类型(0:寻物 1:招领)',
  `item_name` varchar(128) NOT NULL COMMENT '物品名称',
  `description` text COMMENT '物品描述',
  `images` varchar(2048) DEFAULT NULL COMMENT '图片URL(逗号分隔)',
  `location` varchar(256) DEFAULT NULL COMMENT '地点',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态(0:未解决 1:已解决)',
  `audit_status` tinyint NOT NULL DEFAULT '1' COMMENT '审核状态(0:待审核 1:已通过 2:已驳回)',
  `reject_reason` varchar(256) DEFAULT NULL COMMENT '驳回原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_type` (`type`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_audit_status` (`audit_status`),
  KEY `idx_school_audit_time` (`school_id`,`audit_status`,`create_time`),
  CONSTRAINT `fk_lost_found_school` FOREIGN KEY (`school_id`) REFERENCES `school` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_lost_found_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=310 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='失物招领表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `lost_found`
--

