INSERT INTO `lost_found` VALUES (1,1,1,0,'黑色双肩包','今天下午在图书馆二楼自习室丢了一个黑色双肩包，里面有笔记本电脑和几本专业书，对我很重要，捡到必有重谢！','https://picsum.photos/400/300?random=701','图书馆二楼',0,1,NULL,'2026-10-07 11:25:31','2026-10-09 14:38:09',0),(2,2,1,1,'苹果AirPods Pro','在操场跑步的时候捡到的，白色耳机盒，上面有个小恐龙贴纸，失主快来认领。','https://picsum.photos/400/300?random=702','操场看台上',1,1,NULL,'2026-10-07 11:25:31','2026-10-08 16:26:40',0),(3,3,1,0,'校园卡+钥匙','昨天在食堂丢了校园卡和一串钥匙，钥匙上有个小熊挂件，补办卡太麻烦了，求好心人捡到联系我。',NULL,'一食堂一楼',1,1,NULL,'2026-10-07 11:25:31','2026-10-08 16:26:40',0),(4,4,1,1,'雨伞','一教门口捡到一把透明雨伞，伞柄是粉色的，下雨那天好多人丢伞，来认领的时候说一下伞的特征。','https://picsum.photos/400/300?random=703','一教教学楼门口',1,1,NULL,'2026-10-07 11:25:31','2026-10-08 16:26:40',0),(5,5,1,0,'粉色水杯','我的粉色保温杯不见了，上面贴了很多贴纸，是我生日朋友送的，对我意义重大，在三教附近丢的。','https://picsum.photos/400/300?random=704','三教教学楼',1,1,NULL,'2026-10-07 11:25:31','2026-10-08 16:26:40',0),(6,6,1,1,'身份证','在学校南门附近捡到一张身份证，是河南的同学，姓王，我已经交到保卫处了，失主可以去认领。',NULL,'学校南门',1,1,NULL,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(7,7,1,0,'switch游戏机','上周在宿舍楼下的自习室丢了一台switch，蓝色的，里面有我好几个游戏存档，急死我了，找到必有重谢！','https://picsum.photos/400/300?random=705','宿舍楼自习室',1,1,NULL,'2026-10-07 11:25:31','2026-10-08 16:26:40',0),(8,8,1,1,'快递包裹','菜鸟驿站拿错了一个快递，不是我的，是一个叫李同学的，包裹还没拆，我放在驿站前台了。',NULL,'菜鸟驿站',1,1,NULL,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(9,9,1,0,'学生证','学生证丢了，姓名李四，计算机学院，捡到请联系我，奶茶感谢！','https://picsum.photos/400/400?random=707','不确定',1,1,NULL,'2026-10-08 16:23:15','2026-10-08 16:26:40',0),(10,10,1,1,'粉色水杯','在自习室302捡到一个粉色保温杯，膳魔师的，放前台了。','https://picsum.photos/400/400?random=708','自习室302',1,1,NULL,'2026-10-08 16:23:15','2026-10-08 16:26:40',0),(11,12,1,0,'keys','d','','lib',0,1,NULL,'2026-10-09 13:42:31','2026-10-09 13:42:31',0),(12,12,1,0,'E2E keys','a keyring','','library',1,1,NULL,'2026-10-09 13:45:20','2026-10-09 13:45:20',0),(13,12,1,0,'E2E keys','a keyring','','library',1,1,NULL,'2026-10-09 13:51:31','2026-10-09 13:51:31',0),(14,12,1,0,'keys','d','','lib',0,1,NULL,'2026-10-09 13:51:37','2026-10-09 13:51:37',0),(15,12,1,0,'E2E key