  `content` varchar(1024) NOT NULL COMMENT '消息内容',
  `related_id` bigint DEFAULT NULL COMMENT '关联ID(订单ID/帖子ID等)',
  `related_type` varchar(32) DEFAULT NULL COMMENT '关联类型',
