--
-- Table structure for table `post`
--

DROP TABLE IF EXISTS `post`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `post` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '作者ID',
  `school_id` bigint DEFAULT NULL COMMENT '学校ID',
  `title` varchar(128) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '内容',
  `category` varchar(16) NOT NULL DEFAULT '推荐' COMMENT '分类(推荐/吐槽/交友/分享)',
  `images` varchar(2048) DEFAULT NULL COMMENT '图片URL(逗号分隔)',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览量',
  `audit_status` tinyint NOT NULL DEFAULT '1' COMMENT '审核状态(0:待审核 1:已通过 2:已驳回)',
  `is_top` tinyint NOT NULL DEFAULT '0' COMMENT '是否置顶(0:否 1:是)',
  `reject_reason` varchar(256) DEFAULT NULL COMMENT '驳回原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_audit_status` (`audit_status`),
  KEY `idx_school_audit_time` (`school_id`,`audit_status`,`create_time`),
  KEY `idx_school_cate_time` (`school_id`,`category`,`create_time`),
  CONSTRAINT `fk_post_school` FOREIGN KEY (`school_id`) REFERENCES `school` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_post_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=204 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='帖子表';
/*!40101 SET character_set_client = @saved_cs_client */;

