-- Dumping data for table `post`
--

LOCK TABLES `post` WRITE;
/*!40000 ALTER TABLE `post` DISABLE KEYS */;
INSERT INTO `post` VALUES (1,1,1,'食堂三楼新开的麻辣香锅真不错','今天去食堂三楼尝了尝新开的麻辣香锅，味道真的绝了！食材新鲜，味道正宗，价格也实惠，强烈推荐大家去试试，就在最里面那家。','分享','https://picsum.photos/600/400?random=601',520,1,0,NULL,'2026-10-07 11:25:31','2026-10-09 15:30:00',1),(2,2,1,'求推荐靠谱的考研机构','准备25考研，想问问大家有没有推荐的考研机构？最好是线下的，数学和英语比较好的，价格不要太贵，感谢各位学长学姐！','分享',NULL,340,1,0,NULL,'2026-10-07 11:25:31','2026-10-09 15:30:00',0),(3,3,1,'图书馆占座现象太严重了','真的受不了图书馆占座的人了，早上八点去就没位置了，好多座位上放着书但人一整天都不来，希望学校能管管这种现象。','吐槽',NULL,890,1,1,NULL,'2026-10-07 11:25:31','2026-10-09 15:30:00',0),(4,4,1,'校园里的流浪猫有人喂吗','最近在宿舍楼下发现了一只橘猫，特别亲人，想问问有没有人组织喂猫的？我想加入，也想给它做个绝育。','交友','https://picsum.photos/600/400?random=602',256,1,0,NULL,'2026-10-07 11:25:31','2026-10-09 15:30:00',0),(5,5,1,'分享一下我的保研经验','刚刚收到了北大的保研offer，想在这里分享一下我的保研经历，希望对学弟学妹们有帮助。首先成绩一定要好，其次多参加竞赛...','分享',NULL,1250,1,1,NULL,'2026-10-07 11:25:31','2026-10-09 15:30:00',0),(6,6,1,'有没有一起夜跑的小伙伴','每天晚上9点左右在操场跑步，大概跑5公里，有没有想一起的小伙伴？可以互相监督打气，男女不限，速度不用太快。','交友',NULL,178,1,0,NULL,'2026-10-07 11:25:31','2026-10-09 15:30:00',0),(7,7,1,'吐槽一下学校的网','宿舍的网也太慢了吧，打个游戏460延迟，看视频也卡，每个月交那么多网费就这？什么时候能改善一下啊。','推荐',NULL,634,1,0,NULL,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(8,8,1,'捡到一张校园卡','今天在一教门口捡到一张校园卡，是计算机学院的同学，名字就不说了，失主看到私信我认领。','推荐','https://picsum.photos/600/400?random=603',89,1,0,NULL,'2026-10-07 11:25:31','2026-10-07 11:25:31',0),(9,12,1,'t','c','推荐','',0,1,0,NULL,'2026-10-09 13:29:18','2026-10-09 13:29:18',0),(10,12,1,'t','c','推荐','',0,1,0,NULL,'2026-10-09 13:42:31','2026-10-09 13:42:31',0),(13,12,1,'t','c','推荐','',0,1,0,NULL,'2026-10-09 13:51:37','2026-10-09 13:51:37',0),(15,12,1,'t','c','推荐','',0,1,0,NULL,'2026-10-09 14:00:46','2026-10-09 14:00:46',0),(16,12,1,'t','c','推荐','',0,1,0,NULL,'2026-10-09 14:00:57','2026-10-09 14:00:57',0),(17,11,1,'测试平台稳定','111','推荐','',0,1,0,NULL,'2026-10-09 15:08:28','2026-10-11 13:52:56',1),(138,11,1,'耍朋友dd','hello，everyone！！！','交友','',0,1,0,NULL,'2026-10-09 17:17:09','2026-10-09 17:17:09',0),(139,29,1,'CollectTest','c','推荐','',0,1,0,NULL,'2026-10-09 17:36:06','2026-10-11 13:52:56',1),(140,29,1,'CollectFixTest','c','推荐','',0,1,0,NULL,'2026-10-09 17:51:36','2026-10-11 13:52:56',1),(187,11,16,'1','1','吐槽','',0,1,0,NULL,'2026-10-09 19:44:42','2026-10-09 19:44:42',0),(188,39,16,'长期羽毛球队友','测试','交友','',0,1,0,NULL,'2026-10-10 10:58:10','2026-10-10 10:58:10',0),(189,1,1,'图书馆占座太严重了','早上八点去图书馆，六楼的座位全被书占了，人影都没一个。建议学校搞个暂离时限，超时自动释放座位！','吐槽','https://picsum.photos/seed/campus0/600/400',125,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(190,2,1,'期末复习资料整理好了','高数、线代、大英的历年真题和复习笔记都整理在这了，需要的同学自取，祝大家期末顺利！','分享','https://picsum.photos/seed/campus1/600/400',364,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(191,3,1,'有没有一起晨跑的搭子','每天早上六点半操场见，坚持了一个学期了，找几个志同道合的伙伴互相监督！','交友','https://picsum.photos/seed/campus2/600/400',357,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(192,4,1,'食堂二楼的麻辣香锅涨价了','分量还变少了，这谁顶得住啊。隔壁三楼的面馆它不香吗','吐槽','https://picsum.photos/seed/campus3/600/400',307,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(193,5,1,'考研资料低价出','考研数学、英语一、政治全套资料，九成新，仅限本校面交','分享','https://picsum.photos/seed/campus4/600/400',332,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(194,6,1,'找摄影爱好者一起扫街','周末想去老城区拍人文题材，有没有一起的？互相当模特也行','交友','https://picsum.photos/seed/campus5/600/400',209,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(195,7,1,'图书馆前面的樱花开疯了','随手一拍都是壁纸，趁没下雨赶紧去打卡','分享','https://picsum.photos/seed/campus6/600/400',152,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(196,8,1,'宿舍空调什么时候能装上','夏天快到了，每年都提案每年都没消息，联名大家都签了吗','吐槽','https://picsum.photos/seed/campus7/600/400',258,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(197,9,1,'自学编程半年的一点心得','从零基础到能写出完整的后端项目，分享下我的学习路线和踩过的坑','分享','https://picsum.photos/seed/campus8/600/400',345,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(198,10,1,'剧本杀拼车缺3人','周六下午东门新开的店，城限本《云使》，价格AA','交友','https://picsum.photos/seed/campus9/600/400',229,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(199,11,16,'四六级查分啦','616过了！备考经验回头整理一篇长文分享','分享','https://picsum.photos/seed/campus10/600/400',172,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(200,12,NULL,'打印店排队一小时','毕业季打印论文人太多，建议早上八点前去','吐槽','https://picsum.photos/seed/campus11/600/400',427,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(201,13,NULL,'新开的奶茶店测评','点了三款招牌，杨枝甘露最好喝，推荐指数四星','分享','https://picsum.photos/seed/campus12/600/400',444,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(202,14,NULL,'找羽毛球球友','水平一般求带，每周三周五晚上体育馆，场地我订','交友','https://picsum.photos/seed/campus13/600/400',472,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0),(203,15,NULL,'自习宝藏地分享','教学楼五楼尽头的空教室，人少安静还有插座','分享','https://picsum.photos/seed/campus14/600/400',111,1,0,NULL,'2026-10-11 12:15:01','2026-10-11 12:15:01',0);
