/doc2/800/1100',0,'A4',1,0,0,'4栋宿舍楼','同学','13800001234',NULL,0,6.60,2,NULL,NULL,NULL,'2026-10-09 07:27:42','2026-10-11 12:27:42',0),(167,'PRT2026101187638',16,39,NULL,'https://picsum.photos/seed/doc3/800/1100',1,'A4',3,1,0,'16栋宿舍楼','同学','13800001234',NULL,0,4.20,3,NULL,NULL,NULL,'2026-10-04 16:27:42','2026-10-11 12:27:42',0),(168,'PRT2026101121725',1,6,NULL,'https://picsum.photos/seed/doc5/800/1100',0,'A4',3,1,0,'1栋宿舍楼','同学','13800001234',NULL,0,5.40,1,NULL,NULL,NULL,'2026-10-08 00:27:42','2026-10-11 12:27:42',0),(169,'PRT2026101145711',3,46,NULL,'https://picsum.photos/seed/doc9/800/1100',1,'A4',3,1,0,'3栋宿舍楼','同学','13800001234',NULL,0,13.00,1,NULL,NULL,NULL,'2026-10-08 16:27:42','2026-10-11 12:27:42',0),(170,'PRT2026101163379',3,46,NULL,'https://picsum.photos/seed/doc10/800/1100',0,'A4',3,0,0,'3栋宿舍楼','同学','13800001234',NULL,0,6.80,1,NULL,NULL,NULL,'2026-10-06 19:27:42','2026-10-11 12:27:42',0),(171,'PRT2026101179766',1,2,NULL,'https://picsum.photos/seed/doc15/800/1100',1,'A4',4,1,0,'1栋宿舍楼','同学','13800001234',NULL,0,15.20,1,NULL,NULL,NULL,'2026-10-10 20:27:42','2026-10-11 12:27:42',0),(172,'PRT2026101108695',1,5,NULL,'https://picsum.photos/seed/doc16/800/1100',0,'A4',4,0,0,'1栋宿舍楼','同学','13800001234',NULL,0,8.40,2,NULL,NULL,NULL,'2026-10-09 17:27:42','2026-10-11 12:27:42',0),(173,'PRT2026101104173',5,48,NULL,'https://picsum.photos/seed/doc17/800/1100',0,'A4',4,1,0,'5栋宿舍楼','同学','13800001234',NULL,0,8.70,2,NULL,NULL,NULL,'2026-10-09 22:27:42','2026-10-11 12:27:42',0),(174,'PRT2026101194781',1,3,NULL,'https://picsum.photos/seed/doc18/800/1100',1,'A4',1,0,0,'1栋宿舍楼','同学','13800001234',NULL,0,14.90,3,NULL,NULL,NULL,'2026-10-06 17:27:42','2026-10-11 12:27:42',0);
